import { MetadataRoute } from 'next';

/**
 * robots.ts — Programmatic robots.txt generator.
 *
 * FOCUS-5-TASKS — SEO Phase 1 (2026-10-01):
 *   - Allows all major crawlers (Googlebot, Bingbot, Twitterbot, facebookexternalhit).
 *   - Disallows /api/* (internal APIs — not for indexing).
 *   - Disallows /admin/* (admin pages — not for public).
 *   - Points to /sitemap.xml (auto-generated by src/app/sitemap.ts).
 *
 * Reference: Rule 62 (GIT-PUSH-DISCIPLINE).
 */

const SITE_URL = process.env.NEXT_PUBLIC_SITE_URL || 'https://invist.m2y.net';

export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      {
        userAgent: '*',
        allow: '/',
        disallow: [
          '/api/',
          '/admin/',
          '/_next/',
          '/legal/payment-success',
        ],
      },
      // Social crawlers get full access for rich previews.
      {
        userAgent: ['Googlebot', 'Bingbot', 'Twitterbot', 'facebookexternalhit', 'LinkedInBot'],
        allow: '/',
      },
    ],
    sitemap: `${SITE_URL}/sitemap.xml`,
    host: SITE_URL,
  };
}
